import{_ as r,o as t,c as s,a8 as p}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"英华书院 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-82f4b96c","school_zh":"英华书院","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"英华书院 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-YINGWA-FIRST","C2223-YINGWA-MUSIC","C2223-YINGWA-SPORT"],"rounds":["r1","unknown"]},"headers":[],"relativePath":"reports/school-82f4b96c/s1/2022-23-interview.md","filePath":"reports/school-82f4b96c/s1/2022-23-interview.md"}'),e={name:"reports/school-82f4b96c/s1/2022-23-interview.md"};function n(a,o,c,g,l,i){return t(),s("div",null,[...o[0]||(o[0]=[p('<h1 id="英华书院-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">英华书院 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#英华书院-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;英华书院 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-82f4b96c">← 返回英华书院资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-yingwa-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-yingwa-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-yingwa-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>准备与分室评估</strong></p><p>主要分中文及英文、数学及科学两个课室。多份反馈先准备约5分钟，再限时回答；有版本各科约1至1分半钟，也有语言合计3分钟、数学科学合计3分钟。准备时能否记笔记有不同安排，应听从现场指引。</p><p><strong>等候与实际答题</strong></p><p>家长一般在外等候。考生核对面试信后到礼堂，再分组进准备室；一个版本准备室有24人，每组三人，五分钟后收回题纸。有考生下午1时30分至3时52分才完成，也有等候约两小时、实际答题约四分钟的回忆；全程时间不能当作答题时限。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读理解与观点</strong></p><p>文章主题包括金钱与权力、朋友及五伦、人类破坏环境、青少年使用手机和电脑，以及家庭。通常回答约3题，部分另有追问；有场次不要求朗读，也有人读至中途被叫停。问题包括朋友为何重要、是否同意朋友最重要、金钱和权力不能买到什么，以及环境受破坏的后果和解决方法。</p><p><strong>词语、成语与运用</strong></p><p>按句意选择或解释“不可或缺”“要素”等词；已获父母买电脑仍要求手机的情境涉及“贪得无厌”。其他题目包括解释“一孔之见”“坐井观天”“众目睽睽”“一日千里”“一针见血”，并追问“一针”能否改成“两针”或“三针”、为什么。另有学生只记得一组成语首字为“一”、第三字为“九”，无法确认完整题目。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读与理解</strong></p><p>文章有约200词、限时朗读约30秒的版本，也有指定读两段。主题包括身材矮小或坐轮椅的女孩、Monopoly、恐龙灭绝和化石、电脑游戏。老师可能在读至中途叫停，再作问答。</p><p><strong>社会关怀</strong></p><p>围绕身体障碍者遇到的日常困难、为何及如何帮助他们、自己的助人经历，以及政府如何帮助贫困或有需要的人提问。</p><p><strong>生活经验与延伸思考</strong></p><p>是否玩过Monopoly、从中学到什么；曾到访哪些博物馆、看过什么展品，介绍有趣的展览；从恐龙灭绝学到什么，人类未来会否灭绝或迁往其他星球；是否与家人玩电脑游戏、平日用电脑做什么。另有考生记得约四道问题，其中涉及食环署，但未能复述完整题目。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>限时计算与选择</strong></p><p>有版本一分钟答三题；另有按4分、2分、1分标示的题目，选择其中两题。部分场次不提供草稿纸。题型包括数三角形、小数四则运算、数列及奥数式解难。</p><p><strong>不同学生记下的算式</strong></p><p>3.6−0.6÷2；3.6÷0.6÷0.6；3.6÷6÷0.6；4.5−1.5÷0.5；4−1.5÷0.5；36÷0.6÷0.6；4.5÷1.5÷1.5。这些为不同反馈的题目版本，不能据此认定每场都考同一组。</p><p><strong>数列与规律</strong></p><p>例子包括21、28、36、45之后的数字，以及每次依次加2、加3、加4、加5的规律题。另有5、8、13之后的数字，考生对究竟问下一项还是隔一项记忆不确定。</p></blockquote><blockquote><p><strong>科学：</strong> 部分题目中英双语；作答语言未注明</p><p><strong>比较材料并说明选择</strong></p><p>阅读材料性质表，判断哪种适合防火门、消防头盔、面罩、消防服、食物盒或塑料袋，再说明理由。比较指标包括熔点、燃点、耐火时间和受热10秒后的温度变化；有版本约一分钟作答。</p><p><strong>食物盒题设</strong></p><p>一组比较中，X材料的致癌物比例为0.04%、熔点400℃、无需光照即可降解；Y材料为1%、120℃、需要光照。以上数字属于考题条件。另一塑料袋版本记为X为0.01%、Y为2%，并比较降解是否需要光照，但条件与材料的对应关系未能确认，第三项条件也未记清。</p><p><strong>面罩题设</strong></p><p>一个版本给出燃点500℃与3500℃、耐火五分钟与五小时等比较条件；第三项条件未记清。需要结合题设作选择，不能把记忆中的材料数字当作现实产品规格。</p></blockquote><h2 id="record-c2223-yingwa-music" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-yingwa-music" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-yingwa-music}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>音乐评估：</strong> 语言未注明</p><p><strong>准备及演奏</strong></p><p>事前电话通知准备约三分钟乐曲，可与先前提交影片的曲目不同。家长填写主要及第二乐器、最高ABRSM或Trinity级别及考获年份，学生携带证书正本核对；等候时可热身。家长陪同进入，约三位老师在场，考生自行取谱架。老师可能中途叫停，预留问答时间。</p><p><strong>音乐经历</strong></p><p>了解学习乐器多久、是否学过其他乐器、为何转换、遇到什么困难；是否参加乐团、比赛或交流，以及最难忘的经历。其中一位学生以长号学习经历作答。</p><p><strong>择校及时间安排</strong></p><p>为何选择英华、期望学到什么、还有哪些课外活动；如何平衡时间，若只能保留两项活动会如何选择。一个版本预先告知家长只可提出一个问题。</p></blockquote><h2 id="record-c2223-yingwa-sport" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-yingwa-sport" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-yingwa-sport}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>体育评估：</strong> 语言未注明</p><p><strong>专项测试</strong></p><p>部分体育考生另参加专项评估，不能据此认定所有申请人都有此环节。羽毛球包括发球、高远球、扣杀、步法及体能；老师喂球，没有一对一或双打。足球以分组比赛观察表现，各站之间可能等候。</p></blockquote>',25)])])}const u=r(e,[["render",n]]);export{h as __pageData,u as default};
